def word_break(s, word_dict):
    """
    Determines if a string can be segmented into space-separated words from a given dictionary.
    Each word in the dictionary may only be used once.

    Args:
        s: The string to segment
        word_dict: A list or set of valid words (each word can only be used once)

    Returns:
        True if the string can be segmented into words from the dictionary
        (each word used at most once), False otherwise
    """
    word_list = list(word_dict)

    def backtrack(remaining, used):
        if remaining == "":
            return True
        for i, word in enumerate(word_list):
            if i not in used and remaining.startswith(word):
                if backtrack(remaining[len(word):], used | {i}):
                    return True
        return False

    return backtrack(s, set())
